create index if not exists idx_employees_department on employees(department); create index if not exists idx_attendance_employee_date on attendance_records(employee_id,attendance_date); create index if not exists idx_payroll_items_run on payroll_items(payroll_run_id); create index if not exists idx_claims_employee_status on claims(employee_id,status); create index if not exists idx_audit_logs_created_at on audit_logs(created_at);
